const pillS = (T, o) => Object.assign({ 'font-size': '11px', 'font-weight': 700, 'letter-spacing': '1.2px', 'text-transform': 'uppercase', padding: '7px 16px', 'border-radius': '999px', border: '1.5px solid ' + mix(T.accent, T.page, 0.2), color: T.primary, 'box-sizing': 'border-box', 'align-self': 'flex-start' }, o || {});
