const WAVE = (c) => svgUri('<svg xmlns="http://www.w3.org/2000/svg" width="28" height="10" viewBox="0 0 28 10"><path d="M0 5C3.5 0 7 0 10.5 5S17.5 10 21 5s5-5 7 0" fill="none" stroke="' + c + '" stroke-width="1.6"/></svg>');
const wrapRow = (n, T, gap, extra, b) => wrapCss(n, T, { gap, b: b || {} }, extra);
const nick = (p) => g(p.nick, String(p.name || '').split(' ')[0].replace(/,$/, ''));

