    const tx = (a, b) => K(a + '\n' + b, { 'white-space': 'pre-line', '--fs': F(T, 1.2) + 'px', 'font-family': HF(T), 'font-size': F(T, 0.8) + 'px', color: T.text, 'line-height': 1.55, padding: '0 6px' }, 'tcfl');
