  const rgbaOf = (c, a) => { const x = parseC(c); return x ? 'rgba(' + Math.round(x[0]) + ',' + Math.round(x[1]) + ',' + Math.round(x[2]) + ',' + a + ')' : c; };
  const shTok = (s, T) => String(s || '').replace(/tok:(\w+)(?:\/(\d+))?/g, (m, k, a) => { const v = T[k]; if (!v) return 'currentColor'; return a ? rgbaOf(v, (+a / 100).toFixed(2)) : v; });

