    const state = p.previewState === 'off' || p.previewState === 'blocked' ? p.previewState : 'on';
    const playing = state === 'on'; const blocked = state === 'blocked';
    const iconOn = IC[p.iconOn] && p.iconOn !== 'volumex' ? p.iconOn : 'volume';
    const iconOff = IC[p.iconOff] && p.iconOff !== 'volumex' ? p.iconOff : 'music';
