  const cardCss = (P, pad, extra) => Object.assign({ width: '100%', 'box-sizing': 'border-box', background: P.card, 'border-radius': pxs(P.r), padding: pxs(pad), display: 'flex', 'flex-direction': 'column', 'align-items': 'stretch', 'text-align': 'left' }, extra || {});

