const BASE0 = { person: 'center', couple: 'stack', heading: 'center', para: 'plain', divider: 'line', button: 'solid', count: 'box', cover: 'center', open: 'center', sdate: 'big', gal: 'grid', live: 'card', map: 'card', qr: 'card', rsvp: 'stack', guest: 'center', wish: 'list', addr: 'card', quote: 'classic', ti: 'list', dress: 'dots', run: 'timeline', event: 'stack', story: 'line', gift: 'card', marquee: 'text', orn: 'flower', audio: 'pill' };
// view hasil port hai.undangyah.id: tampilan dasar = preset paling polos yang menghormati semua properti
const HAI_BASE = { couple: 'classic-stack', person: 'minimal-profile', open: 'open-ivory-script' };
const NONE_LABEL = 'Tanpa preset';
const NONE_SHOW = {}; // view -> path field yang tetap tampil walau bergantung preset
const NONE_HIDE = {}; // view -> path field yang tidak berlaku pada tampilan dasar
