// ---------- Snap antar section (Pratinjau): satu gulir roda mouse = pindah ke section berikutnya ----------
// Section yang lebih tinggi dari layar tetap digulir normal sampai tepi bawah/atasnya terlihat.
const snapFlip = (sc, e, lock) => {
  try { if (getComputedStyle(sc).overflowY === 'hidden') { e.preventDefault(); return true; } } catch (x) {}
  const dy = e.deltaY; if (!dy || Math.abs(dy) < 2) return false;
  const pg = sc.querySelector('#tcPage'); if (!pg) return false;
  const rs = sc.getBoundingClientRect(); const st = sc.scrollTop; const vh = sc.clientHeight;
  const secs = []; Array.prototype.forEach.call(pg.children, (c) => {
    if (!c.getAttribute || !c.getAttribute('data-nid')) return;
    let al = ''; try { al = getComputedStyle(c).scrollSnapAlign || ''; } catch (x) {}
    if (al.indexOf('start') < 0) return;
    const r = c.getBoundingClientRect(); const top = r.top - rs.top + st; secs.push({ top, bot: top + r.height });
  });
  if (!secs.length) return false;
  if (lock.t && Date.now() < lock.t) { e.preventDefault(); return true; }
  let cur = 0; secs.forEach((x, i) => { if (x.top <= st + 8) cur = i; });
  const c = secs[cur]; let target = null;
  if (dy > 0) {
    if (c.bot > st + vh + 8) return false;
    if (!secs[cur + 1]) return false;
    target = secs[cur + 1].top;
  } else if (st > c.top + 8) {
    if (c.bot - c.top > vh + 8) return false;
    target = c.top;
  } else if (secs[cur - 1]) target = secs[cur - 1].top;
  else return false;
  e.preventDefault(); lock.t = Date.now() + 650; sc.scrollTo({ top: target, behavior: 'smooth' });
  return true;
};
