const HEXOK = /^#[0-9a-fA-F]{6}$/;
const readCat = () => { let raw = []; try { raw = JSON.parse(localStorage.getItem('undangyah-themes') || '[]'); } catch (e) { raw = []; } return Array.isArray(raw) ? raw : []; };
const writeCat = (arr) => { try { localStorage.setItem('undangyah-themes', JSON.stringify(arr)); } catch (e) {} };
