  if (/great vibes|script|cursive|pinyon|allura|parisienne|sacramento|tangerine|dancing|caveat|satisfy|pacifico|snell|chancery|brush/i.test(v)) return 'script';
  if (/sans-serif|system-ui|-apple-system|helvetica|arial|inter\b|poppins|jost|manrope|karla|montserrat|work sans|dm sans|space grotesk|roboto|open sans|lato/i.test(v)) return 'body';
  if (/serif|georgia|cormorant|playfair|new york|garamond|baskerville|lora|merriweather|cinzel|forum|marcellus|italiana|crimson|didot/i.test(v)) return 'head';
