const xFont = (p, slot) => { const v = p[{ head: 'xFHead', script: 'xFScript', body: 'xFBody' }[slot]]; return v ? "'" + String(v).replace(/[^A-Za-z0-9 \-]/g, '') + "'," + XFALL[slot] : ''; };
