// =====================================================================
//  q_mb.js — Metabox: tautan data widget ke input di halaman Edit Undangan
//  Katalog (q_mbdata.js, dihasilkan dari Edit Undangan): section, field teks, daftar berulang, slot foto.
//  Tautan disimpan di n.p.mbl[<jalur p.* tanpa "p." dan titik→_>] = kunci field | 'photo:<slot>' | 'list:<daftar>' | 'none'.
//  Tanpa isian di mbl = pakai tautan bawaan jenis widget (MBDEF). 'none' = diputus.
//  Pratinjau kanvas: kolom teks/daftar yang terhubung memakai contoh dari Edit Undangan; foto tetap foto contoh.
// =====================================================================
const mbBr = (s) => '{' + '{' + s + '}' + '}'; // kurung kurawal ganda disusun lewat penggabungan
const mbSlug = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
const MBF = {}; MBD.F.forEach((f) => { MBF[f[0]] = { key: f[0], sec: f[1], label: f[2], sample: f[3], kind: f[4] }; });
// MBLIVE: data asli undangan terbit (halaman tamu). null = pratinjau tema memakai contoh dari Edit Undangan.
let MBLIVE = null;
const mbSetLive = (L) => { MBLIVE = L || null; };
const mbRowsOf = (src) => (MBLIVE ? (MBLIVE.rows(src) || []) : (MBD.L[src] ? MBD.L[src].rows : []));
const mbEv = (i) => { const r = (mbRowsOf('ev')[0] || []); return r[i] == null ? '' : r[i]; };
const MBVF = {
  'v:namaCover': { sec: 'sampul', label: 'Nama panggilan pasangan (pria & wanita)', sample: (MBF.priaP ? MBF.priaP.sample : '') + ' & ' + (MBF.wanitaP ? MBF.wanitaP.sample : ''), tok: 'sampul_nama_pasangan' },
  'v:ev1_tgl': { sec: 'acara', label: 'Acara pertama › Tanggal', sample: mbEv(1), tok: 'acara_1_tgl' },
  'v:ev1_jam': { sec: 'acara', label: 'Acara pertama › Jam', sample: mbEv(2), tok: 'acara_1_jam' },
  'v:ev1_lokasi': { sec: 'acara', label: 'Acara pertama › Lokasi', sample: mbEv(3), tok: 'acara_1_lokasi' },
  'v:ev1_alamat': { sec: 'acara', label: 'Acara pertama › Alamat', sample: mbEv(4), tok: 'acara_1_alamat' },
  'v:ev1_btn': { sec: 'acara', label: 'Acara pertama › Teks tombol peta', sample: mbEv(5), tok: 'acara_1_maps_btn' },
  'v:ev1_maps': { sec: 'acara', label: 'Acara pertama › Link Google Maps', sample: mbEv(6), tok: 'acara_1_maps' },
  'v:inisial': { sec: 'sampul', label: 'Inisial pasangan (mis. R · S)', sample: String((MBF.priaP ? MBF.priaP.sample : '?').charAt(0)).toUpperCase() + ' · ' + String((MBF.wanitaP ? MBF.wanitaP.sample : '?').charAt(0)).toUpperCase(), tok: 'sampul_inisial' },
  'v:gl_video': { sec: 'gallery', label: 'Link video YouTube galeri', sample: '', tok: 'gallery_video' },
  'v:monogram': { sec: 'sampul', label: 'Monogram pasangan (mis. R & S)', sample: String((MBF.priaP ? MBF.priaP.sample : '?').charAt(0)).toUpperCase() + ' & ' + String((MBF.wanitaP ? MBF.wanitaP.sample : '?').charAt(0)).toUpperCase(), tok: 'sampul_monogram' },
  'v:live_jadwal': { sec: 'livestream', label: 'Jadwal siaran (tanggal + jam)', sample: (MBF.lvTgl ? MBF.lvTgl.sample : '') + ' · ' + (MBF.lvMulai ? MBF.lvMulai.sample : '') + ' WIB', tok: 'livestream_jadwal' },
};
const mbSecName = (s) => (s === 'bgfixed' ? 'Background Fixed' : (MBD.sec[s] || s));
const mbTok = (key) => {
  if (key.indexOf('v:') === 0) return mbBr('_' + MBVF[key].tok);
  if (key.indexOf('photo:') === 0) { const s = key.slice(6); if (s === 'bgf') return mbBr('_background_fixed_image_url'); if (/^bgs\d$/.test(s)) return mbBr('_background_fixed_slide_' + s.slice(3) + '_url'); if (s === 'gallery') return mbBr('_gallery_foto_N_url'); if (/^g\d+$/.test(s)) return mbBr('_gallery_foto_' + s.slice(1) + '_url'); return mbBr('_foto_' + s + '_url'); }
  if (key.indexOf('list:') === 0) return mbBr('_' + (MBD.L[key.slice(5)] ? MBD.L[key.slice(5)].g : key.slice(5)) + '_N_*');
  const f = MBF[key]; return f ? mbBr('_' + f.sec + '_' + mbSlug(f.label)) : '';
};
const mbV = (k) => (MBLIVE ? String(MBLIVE.val(k) == null ? '' : MBLIVE.val(k)) : (MBF[k] ? MBF[k].sample : ''));
const mbVirt = (key) => {
  const ini = (k) => String(mbV(k) || '?').charAt(0).toUpperCase();
  switch (key) {
    case 'v:namaCover': return mbV('priaP') + ' & ' + mbV('wanitaP');
    case 'v:ev1_tgl': return mbEv(1); case 'v:ev1_jam': return mbEv(2); case 'v:ev1_lokasi': return mbEv(3); case 'v:ev1_alamat': return mbEv(4); case 'v:ev1_btn': return mbEv(5); case 'v:ev1_maps': return mbEv(6);
    case 'v:live_jadwal': return mbV('lvTgl') + ' · ' + mbV('lvMulai') + ' WIB';
    case 'v:inisial': return ini('priaP') + ' · ' + ini('wanitaP');
    case 'v:monogram': return ini('priaP') + ' & ' + ini('wanitaP');
    case 'v:gl_video': return MBLIVE && MBLIVE.gvideo ? MBLIVE.gvideo() : '';
    default: return MBVF[key] ? MBVF[key].sample : '';
  }
};
const mbSample = (key) => {
  if (key.indexOf('v:') === 0) return mbVirt(key);
  if (MBLIVE && MBLIVE.guestKeys && MBLIVE.guestKeys[key] && MBLIVE.guest) return MBLIVE.guest(key);
  return mbV(key);
};
const mbLabel = (key) => {
  if (key.indexOf('v:') === 0) return MBVF[key] ? mbSecName(MBVF[key].sec) + ' › ' + MBVF[key].label : key;
  if (key.indexOf('photo:') === 0) { const s = key.slice(6); if (s === 'gallery') return 'Gallery › semua foto'; const p = MBD.P.find((x) => x[0] === s); return p ? mbSecName(p[2]) + ' › ' + p[1] : key; }
  if (key.indexOf('list:') === 0) return mbListLabel(key.slice(5));
  const f = MBF[key]; return f ? mbSecName(f.sec) + ' › ' + f.label : key;
};
